    ["mouv", "mus", "ste"].forEach(function (k) { h += '<button class="gs-tab' + (k === tab ? " on" : "") + '" aria-pressed="' + (k === tab) + '" data-guide="tab-' + k + '">' + t[k] + "</button>"; });
